namespace Invoicing;

/// <summary>Resolves the VAT due for a net amount given account and jurisdiction.</summary>
public sealed class VatResolver
{
    public decimal Resolve(Account account, decimal net, string countryCode)
    {
        if (net <= 0m)
            return 0m;

        decimal rate;
        switch (countryCode)
        {
            case "GB":
                rate = 0.20m;
                break;
            case "DE":
                rate = 0.19m;
                break;
            case "FR":
                rate = 0.20m;
                break;
            case "IE":
                rate = 0.23m;
                break;
            default:
                rate = 0.0m;
                break;
        }

        if (account.Kind == AccountKind.Government)
            rate = 0m;
        else if (account.Kind == AccountKind.Business && net > 10000m)
            rate *= 0.5m;

        if (rate > 0m && net > 100000m)
            rate = Math.Min(rate, 0.15m);

        return net * rate;
    }
}

